const assert = require('node:assert/strict');
const { OrderHandler } = require('../.build/handler');
const { OrderRepository } = require('../.build/repository');

const order = (id, tenant, createdAt, total = 0) => ({ id, tenant, createdAt, total });

// ---------------------------------------------------------------------------
// Sorting: ascending createdAt, then id lexicographically.
// ---------------------------------------------------------------------------
{
  const handler = new OrderHandler(new OrderRepository([
    order('b', 'a', '2026-01-02'),
    order('x', 'b', '2026-01-01'),
    order('c', 'a', '2026-01-01'),
    order('a', 'a', '2026-01-01'),
    order('d', 'a', '2026-01-03')
  ]));
  const page = handler.list({ tenant: 'a', limit: 100 });
  assert.deepEqual(page.items.map(x => x.id), ['a', 'c', 'b', 'd']);
  assert.equal(page.nextCursor, null);
}

// ---------------------------------------------------------------------------
// Tenant filter + limit behavior without a cursor (and nextCursor present).
// ---------------------------------------------------------------------------
{
  const handler = new OrderHandler(new OrderRepository([
    order('a1', 'a', '2026-01-01'),
    order('a2', 'a', '2026-01-02'),
    order('a3', 'a', '2026-01-03'),
    order('b1', 'b', '2026-01-01'),
    order('b2', 'b', '2026-01-02')
  ]));
  const page = handler.list({ tenant: 'a', limit: 2 });
  assert.deepEqual(page.items.map(x => x.id), ['a1', 'a2']);
  assert.equal(page.nextCursor, '2026-01-02|a2');

  const last = handler.list({ tenant: 'a', limit: 2, cursor: page.nextCursor });
  assert.deepEqual(last.items.map(x => x.id), ['a3']);
  assert.equal(last.nextCursor, null);

  const empty = handler.list({ tenant: 'nope', limit: 5 });
  assert.deepEqual(empty.items, []);
  assert.equal(empty.nextCursor, null);
}

// ---------------------------------------------------------------------------
// nextCursor is null exactly when no further matching order exists.
// ---------------------------------------------------------------------------
{
  const handler = new OrderHandler(new OrderRepository([
    order('a', 't', '2026-01-01'),
    order('b', 't', '2026-01-02'),
    order('c', 't', '2026-01-03')
  ]));
  assert.equal(handler.list({ tenant: 't', limit: 3 }).nextCursor, null); // exact fit
  assert.equal(handler.list({ tenant: 't', limit: 5 }).nextCursor, null); // fewer than limit
  assert.equal(handler.list({ tenant: 't', limit: 1 }).nextCursor, '2026-01-01|a'); // more exist
  assert.equal(handler.list({ tenant: 't', limit: 100 }).nextCursor, null);
}

// ---------------------------------------------------------------------------
// Full traversal: no repeats, no skips, proper ordering, equal dates included.
// ---------------------------------------------------------------------------
{
  const rows = [];
  rows.push(order('a', 't', '2026-01-01')); // equal dates, id tie-break
  rows.push(order('c', 't', '2026-01-01'));
  rows.push(order('b', 't', '2026-01-01'));
  rows.push(order('e', 't', '2026-01-02'));
  rows.push(order('d', 't', '2026-01-02'));
  rows.push(order('f', 't', '2026-01-03'));
  rows.push(order('x', 'other', '2026-01-01'));

  for (const limit of [1, 2, 3, 5, 10]) {
    const handler = new OrderHandler(new OrderRepository(rows));
    const seen = [];
    let cursor;
    for (let guard = 0; guard < 50; guard++) {
      const request = { tenant: 't', limit };
      if (cursor !== undefined) request.cursor = cursor;
      const page = handler.list(request);
      assert.ok(page.items.length <= limit);
      seen.push(...page.items.map(x => x.id));
      if (page.nextCursor === null) break;
      cursor = page.nextCursor;
    }
    assert.deepEqual(seen, ['a', 'b', 'c', 'd', 'e', 'f'], `limit ${limit}`);
  }
}

// ---------------------------------------------------------------------------
// Cursor resumes strictly after the pair even when its row was deleted.
// ---------------------------------------------------------------------------
{
  const rows = [
    order('a', 't', '2026-01-01'),
    order('b', 't', '2026-01-01'),
    order('c', 't', '2026-01-02'),
    order('d', 't', '2026-01-02')
  ];
  const handler = new OrderHandler(new OrderRepository(rows));
  const first = handler.list({ tenant: 't', limit: 2 });
  assert.deepEqual(first.items.map(x => x.id), ['a', 'b']);
  assert.equal(first.nextCursor, '2026-01-01|b');

  // Delete the cursor row (and the one before it) from the source data.
  rows.splice(0, 2);

  const second = handler.list({ tenant: 't', limit: 2, cursor: first.nextCursor });
  assert.deepEqual(second.items.map(x => x.id), ['c', 'd']);
  assert.equal(second.nextCursor, null);

  // A cursor bound to a position that no longer exists mid-date still resumes.
  const mid = handler.list({ tenant: 't', limit: 2, cursor: '2026-01-02|b' });
  assert.deepEqual(mid.items.map(x => x.id), ['c', 'd']);
}

// ---------------------------------------------------------------------------
// Filtering precedes pagination: cursor pair from another tenant.
// ---------------------------------------------------------------------------
{
  const handler = new OrderHandler(new OrderRepository([
    order('a1', 'a', '2026-01-01'),
    order('a2', 'a', '2026-01-03'),
    order('b1', 'b', '2026-01-02'),
    order('b2', 'b', '2026-01-04')
  ]));

  // Position key comes from tenant b, but the tenant filter is applied first.
  const page = handler.list({ tenant: 'a', limit: 10, cursor: '2026-01-02|b1' });
  assert.deepEqual(page.items.map(x => x.id), ['a2']);
  assert.equal(page.nextCursor, null);

  const before = handler.list({ tenant: 'a', limit: 10, cursor: '2026-01-01|a1' });
  assert.deepEqual(before.items.map(x => x.id), ['a2']);

  const afterAll = handler.list({ tenant: 'a', limit: 10, cursor: '2026-01-09|b2' });
  assert.deepEqual(afterAll.items, []);
  assert.equal(afterAll.nextCursor, null);
}

// ---------------------------------------------------------------------------
// Repository: filter/sort/cursor, never mutates input array or rows.
// ---------------------------------------------------------------------------
{
  const rows = Object.freeze([
    Object.freeze(order('b', 'a', '2026-01-02')),
    Object.freeze(order('x', 'b', '2026-01-01')),
    Object.freeze(order('a', 'a', '2026-01-01'))
  ]);
  const repo = new OrderRepository(rows);
  assert.deepEqual(repo.list('a').map(x => x.id), ['a', 'b']);
  assert.deepEqual(repo.list('a', { createdAt: '2026-01-01', id: 'a' }).map(x => x.id), ['b']);
  assert.deepEqual(repo.list('a', { createdAt: '2026-01-01', id: 'z' }).map(x => x.id), ['b']);
  assert.deepEqual(repo.list('a', undefined, 1).map(x => x.id), ['a']);
  assert.deepEqual(rows.map(x => x.id), ['b', 'x', 'a']);
}

// ---------------------------------------------------------------------------
// Handler never mutates the repository's rows; deep snapshot comparison.
// ---------------------------------------------------------------------------
{
  const rows = [
    order('b', 'a', '2026-01-02', 2),
    order('x', 'b', '2026-01-01', 3),
    order('a', 'a', '2026-01-01', 1)
  ];
  const snapshot = JSON.stringify(rows);
  const arrayOrder = rows.map(x => x.id).join(',');
  const handler = new OrderHandler(new OrderRepository(rows));
  handler.list({ tenant: 'a', limit: 1 });
  handler.list({ tenant: 'a', limit: 1, cursor: '2026-01-01|a' });
  handler.list({ tenant: 'a', limit: 100 });
  handler.list({ tenant: 'b', limit: 2 });
  assert.equal(JSON.stringify(rows), snapshot);
  assert.equal(rows.map(x => x.id).join(','), arrayOrder);
}

// ---------------------------------------------------------------------------
// Invalid requests.
// ---------------------------------------------------------------------------
{
  const handler = new OrderHandler(new OrderRepository([order('a', 't', '2026-01-01')]));
  const badRequests = [
    { tenant: '', limit: 1 },
    { tenant: null, limit: 1 },
    { tenant: undefined, limit: 1 },
    { tenant: 't', limit: 0 },
    { tenant: 't', limit: 101 },
    { tenant: 't', limit: -1 },
    { tenant: 't', limit: 1.5 },
    { tenant: 't', limit: NaN },
    { tenant: 't', limit: Infinity },
    { tenant: 't', limit: '5' },
    { tenant: 't', limit: 1, cursor: '' },
    { tenant: 't', limit: 1, cursor: '|' },
    { tenant: 't', limit: 1, cursor: 'a|' },
    { tenant: 't', limit: 1, cursor: '|b' },
    { tenant: 't', limit: 1, cursor: 'a|b|c' },
    { tenant: 't', limit: 1, cursor: null },
    { tenant: 't', limit: 1, cursor: 5 }
  ];
  for (const request of badRequests) {
    assert.throws(() => handler.list(request), /^Error: invalid request$/, JSON.stringify(request));
  }
  // Valid boundaries and valid two-part cursors do not throw.
  assert.equal(handler.list({ tenant: 't', limit: 1 }).items.length, 1);
  assert.equal(handler.list({ tenant: 't', limit: 100 }).items.length, 1);
  assert.equal(handler.list({ tenant: 't', limit: 1, cursor: 'not-a-date|some-id' }).items.length, 0);
}

console.log('pagination checks passed');

